// Retirement of contract-codegen artifacts when a package opts out.
//
// ── The hole this closes ──────────────────────────────────────────────
//
// A package opts out of contract codegen either centrally (forge.yaml
// `contracts.exclude`) or locally (`//forge:exclude-contract` in its own
// source). Both are honoured by SKIPPING the package in the mock walk —
// and, until this file existed, by nothing else. Whatever forge had
// already emitted there stayed on disk, certified with forge's
// `// Code generated by forge. DO NOT EDIT.` banner and its forge:hash
// marker, at a path no emitter would ever target again.
//
// That leftover is not merely untidy, it is UNREACHABLE. Two mechanisms
// could resolve a certified file, and an opted-out artifact escapes
// both:
//
//   - the Tier-1 writer (checksums.WriteGeneratedFile) re-stamps
//     anything it rewrites — including a file whose marker went stale
//     while its body stayed byte-identical to the render. It never runs
//     here: the walk returned before reaching the emitter.
//   - the stale-artifact sweep (cli/generate_cleanup.go) retires
//     certified files the run did not re-emit — but only PRISTINE ones.
//     Once the leftover's marker goes stale it is reclassified as
//     "stale AND hand-edited: the bytes are the user's now", reported
//     and never removed.
//
// So the moment anything perturbs the bytes of an opted-out artifact —
// a repo-wide text sweep over the ownership banner is the observed
// case — it becomes permanently un-healable: `forge lint
// --generated-drift` fails on it forever and no forge command moves it.
// (Observed in forge's own tree: internal/config/mock_gen.go, opted out
// two months after it was generated, then caught by a banner sweep.)
//
// Retirement closes the hole at its source. Opting out is an ownership
// EXIT, not a skip: forge gives the path back, and giving it back means
// removing the artifact forge put there — the same discipline
// removeLegacyWrappers already applies to the superseded observability
// wrappers.
//
// ── Why this is safe ──────────────────────────────────────────────────
//
// Retirement deletes only bytes forge can PROVE are its own, and there
// are exactly two proofs:
//
//  1. the embedded marker verifies (checksums.ClassifyPath == Pristine,
//     which already tolerates .go formatter churn) — forge's own render
//     of some vintage, hand-edited by nobody;
//  2. the marker is stale but the body is byte-identical to what forge
//     renders RIGHT NOW (canonical-formatting-insensitive). Only the
//     certificate went stale; there is no content difference, therefore
//     nothing user-authored to lose. Available for mock_gen.go, the one
//     artifact this package can re-render on demand.
//
// Everything else is kept and reported, never deleted:
//
//   - no marker at all — forge never certified those bytes;
//   - a marker that fails to verify AND a body that differs from the
//     render — a genuine hand-edit, which is the user's to resolve;
//   - a disowned path — ownership was already transferred by recorded
//     intent, and `forge project disown` is one-way.
package contract

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"

	"github.com/reliant-labs/forge/internal/checksums"
)

// mockFileName is the mock artifact's filename in a contract package.
const mockFileName = "mock_gen.go"

// retirableArtifacts are the files contract codegen owns inside a
// package directory. The observability wrappers are listed because
// earlier forge versions emitted them from this same walk; a package
// that opts out today may still be carrying one.
var retirableArtifacts = []string{
	mockFileName,
	"middleware_gen.go",
	"tracing_gen.go",
	"metrics_gen.go",
}

// ArtifactSnapshot holds the bytes of the files contract codegen owns in one
// package directory (a nil entry: the file was absent), taken before a run so
// the caller can say whether the run changed them. No single write's outcome
// can: GenerateWithOptions deletes middleware_gen.go and the decorator step
// writes it back, so a package whose output is byte-identical still sees a
// delete and a create every run.
type ArtifactSnapshot map[string][]byte

// SnapshotArtifacts records the current bytes of dir's contract artifacts.
func SnapshotArtifacts(dir string) ArtifactSnapshot {
	snap := ArtifactSnapshot{}
	for _, name := range retirableArtifacts {
		if b, err := os.ReadFile(filepath.Join(dir, name)); err == nil {
			snap[name] = b
		} else {
			snap[name] = nil
		}
	}
	return snap
}

// ChangedIn reports whether any of dir's contract artifacts now differs from
// the snapshot: different bytes, created, or deleted.
func (s ArtifactSnapshot) ChangedIn(dir string) bool {
	now := SnapshotArtifacts(dir)
	for _, name := range retirableArtifacts {
		before, after := s[name], now[name]
		if (before == nil) != (after == nil) || !bytes.Equal(before, after) {
			return true
		}
	}
	return false
}

// IsRetirableArtifact reports whether base (a bare filename) is one of
// the artifacts contract codegen owns inside a package directory.
// Exported so the stomp guard can recognise these paths without
// duplicating the list.
func IsRetirableArtifact(base string) bool {
	for _, name := range retirableArtifacts {
		if base == name {
			return true
		}
	}
	return false
}

// Retirement is the outcome of one retirement sweep. Both slices hold
// project-relative slash paths (or, with no project root in scope,
// absolute ones) so callers can report them verbatim.
type Retirement struct {
	// Retired lists artifacts removed from disk — provably forge's own
	// bytes, so nothing was lost.
	Retired []string
	// Kept lists artifacts left in place because forge could not prove
	// the bytes were its own. Callers should surface these: forge no
	// longer emits them, so only the user can resolve them.
	Kept []string
}

// RetireExcludedArtifacts retires the contract-codegen artifacts forge
// previously emitted into dir, for a package that has since opted out
// of contract codegen. It never recurses — the per-package
// `//forge:exclude-contract` directive opts out exactly one package,
// and a central `contracts.exclude` entry is swept a directory at a
// time by the caller.
//
// A missing artifact is not an error: the steady state for a package
// that opted out before forge ever generated for it is that there is
// nothing to retire, and the sweep is a no-op on every subsequent run.
func RetireExcludedArtifacts(dir string, opts Options) (Retirement, error) {
	var out Retirement
	for _, name := range retirableArtifacts {
		full := filepath.Join(dir, name)
		onDisk, readErr := os.ReadFile(full)
		if os.IsNotExist(readErr) {
			continue
		}
		if readErr != nil {
			return out, fmt.Errorf("read %s: %w", full, readErr)
		}

		rel := displayPath(opts.ProjectRoot, full)
		if opts.Checksums.IsDisowned(rel) {
			// Ownership already transferred by recorded intent — forge
			// does not get to delete it, and its marker was stripped at
			// disown time so no gate flags it either.
			continue
		}

		if !forgeOwnsBytes(dir, rel, name, onDisk, opts) {
			out.Kept = append(out.Kept, rel)
			continue
		}
		// Journaled: retirement is correct on a run that SUCCEEDS, but an
		// aborted run must hand the tree back exactly as it found it.
		checksums.RecordPreWriteAbs(full)
		if err := os.Remove(full); err != nil && !os.IsNotExist(err) {
			return out, fmt.Errorf("retire %s: %w", full, err)
		}
		out.Retired = append(out.Retired, rel)
	}
	return out, nil
}

// forgeOwnsBytes reports whether onDisk is provably forge's own output
// — the delete gate documented in this file's header. False is the
// conservative answer and always means "keep the file".
func forgeOwnsBytes(dir, rel, name string, onDisk []byte, opts Options) bool {
	root := opts.ProjectRoot
	if root == "" {
		root = dir
	}
	switch checksums.ClassifyPath(root, rel, onDisk) {
	case checksums.NoMarker:
		// Forge never certified these bytes. Not ours to remove.
		return false
	case checksums.Pristine:
		return true
	}

	// Marker present but stale. The bytes can still be forge's own — a
	// text sweep over the ownership banner produces exactly this state —
	// so compare against a fresh render before concluding "hand-edit".
	// Only mock_gen.go is re-renderable here; for the rest a stale
	// marker is the end of the evidence.
	if name != mockFileName {
		return false
	}
	render, ok := renderCurrentMock(dir, opts)
	if !ok {
		return false
	}
	return checksums.CanonicalBodyHash(root, rel, onDisk) ==
		checksums.CanonicalBodyHash(root, rel, render)
}

// renderCurrentMock renders what forge's mock template would produce for
// the package rooted at dir right now. ok=false when there is nothing to
// render from (no contract.go, or it no longer parses) — in which case
// the caller has no render to compare against and must keep the file.
func renderCurrentMock(dir string, opts Options) ([]byte, bool) {
	contractPath := filepath.Join(dir, "contract.go")
	cf, err := ParseContractWith(contractPath, opts.Resolver)
	if err != nil {
		return nil, false
	}
	rendered, err := renderMock(cf, opts)
	if err != nil {
		return nil, false
	}
	return rendered, true
}

// displayPath renders full as a project-relative slash path when a
// project root is in scope, and verbatim otherwise. The relative form is
// what the checksums state files are keyed by, so it is also what the
// disowned lookup needs.
func displayPath(projectRoot, full string) string {
	if projectRoot == "" {
		return full
	}
	rel, err := filepath.Rel(projectRoot, full)
	if err != nil {
		return full
	}
	return filepath.ToSlash(rel)
}
